class Command(BaseCommand):
    help = "Load the bundled starter standard catalogue (verify before regulatory use)."

    def add_arguments(self, parser):
        parser.add_argument(
            "--overwrite", action="store_true",
            help="Update existing rows instead of skipping them.",
        )

    @transaction.atomic
    def handle(self, *args, **options):
        overwrite = options["overwrite"]

        categories = {}
        for name, code, order in CATEGORIES:
            obj, _created = CatalogueCategory.objects.update_or_create(
                code=code, defaults={"name": name, "sort_order": order}
            )
            categories[code] = obj
        self.stdout.write(f"Categories: {len(categories)}")

        created = updated = skipped = 0
        for (generic, brand, strength, form, route, atc, cat_code, schedule,
             ptype, unit, essential, cold) in PRODUCTS:
            defaults = {
                "route": route,
                "atc_code": atc,
                "category": categories.get(cat_code),
                "schedule": schedule,
                "product_type": ptype,
                "default_unit": unit,
                "is_essential": essential,
                "requires_cold_chain": cold,
                # Sourced from the Ethiopian EML / WHO Model List — see the
                # module docstring for the exact provenance.
                "data_source": DataSource.WHO_EML,
            }
            lookup = {
                "generic_name": generic, "brand_name": brand,
                "strength": strength, "dosage_form": form,
            }
            existing = CatalogueProduct.objects.filter(**lookup).first()
            if existing and not overwrite:
                skipped += 1
                continue
            if existing:
                for key, value in defaults.items():
                    setattr(existing, key, value)
                existing.save()
                updated += 1
            else:
                CatalogueProduct.objects.create(**lookup, **defaults)
                created += 1

        self.stdout.write(self.style.SUCCESS(
            f"Catalogue: {created} created, {updated} updated, {skipped} skipped "
            f"({CatalogueProduct.objects.count()} total)."
        ))
        self.stdout.write(self.style.WARNING(
            "This is the WHO/Ethiopian Essential Medicines List (essential "
            "medicines only, ~600 entries) — not a full product registry. "
            "For every EFDA-registered product, essential or not, see "
            "docs/CATALOGUE_IMPORT.md and `import_catalogue`."
        ))
